function getOptionValueAtPath(options, path) {
    let currentPath = path;
    let currentValue;

    // Splitting the path into parts for easier traversal
    const parts = currentPath.split('.');

    while (parts.length > 1) {
        // Get the last part of the path
        const lastPart = parts.pop();

        if (!options[lastPart]) {
            break; // If the property does not exist, exit early
        }

        // Recursively navigate through the properties
        currentValue = options[lastPart];
        options = currentValue;
    }

    // Check if there is only one part left in the path
    if (parts.length === 1 && !currentValue) {
        throw new Error(`Key '${path}' not found.`);
    }

    // Return the final result or null if the path doesn't lead to anything
    return parts.length === 1 ? options[parts[0]] : undefined;
}

